(async () => {
  const w_slots = {
  "visitor": {
    "name": "Sam",
    "age": 34,
    "homeVest": true,
    "arrival": "9:10"
  },
  "minor": {
    "name": "Tess",
    "age": 17
  },
  "openFrom": "8:00",
  "openUntil": "16:00",
  "intermittentAlarm": true
};
  const w_answer = await (async () => {
const slots = w_slots;
const visitorClause = slots.visitor.homeVest
  ? slots.visitor.name + " may not enter in the home vest (the rail vest is required)."
  : slots.visitor.name + " may enter in the rail vest.";
const minorClause = slots.minor.age < 18
  ? slots.minor.name + " may not enter: under 18; the cabin is still inside the perimeter."
  : slots.minor.name + " may enter: adult and willing to wait outside the perimeter.";
const alarmClause = slots.intermittentAlarm
  ? "The intermittent alarm means stay put."
  : "The continuous alarm means leave by the east gate.";
return visitorClause + " " + minorClause + " " + alarmClause;
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "place": "Station Quarter",
  "renter": "Cara",
  "staff": "Drew",
  "termDays": 7,
  "returnDays": 9,
  "lateDays": 2,
  "deposit": 270,
  "depositArticle": 4,
  "latePerDay": 25,
  "batteryLimit": 50,
  "batteryKeep": 30,
  "batteryPercent": 40,
  "scratchCm": 8,
  "changeArticle": 9
};
  const w_answer = await (async () => {
const slots = w_slots;
const lateTotal = slots.lateDays * slots.latePerDay;
const lateClause = "Late fee " + slots.lateDays + "×" + slots.latePerDay + "=" + lateTotal + ".";
const batteryClause = slots.batteryPercent < slots.batteryLimit
  ? "Battery " + slots.batteryPercent + "%<" + slots.batteryLimit + "% → " + slots.batteryKeep + " from the deposit."
  : "Battery " + slots.batteryPercent + "%≥" + slots.batteryLimit + "% → nothing kept from the deposit.";
const depositClause = "The scratch cancels the duty to return the deposit in full (Art. " + slots.depositArticle + ").";
const speechClause = "Speech does not amend Art. " + slots.changeArticle + ".";
const cashClause = "Return is not “same day cash”.";
return [lateClause, batteryClause, depositClause, speechClause, cashClause].join(" ");
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "place": "Little River",
  "author": "Hugo",
  "deckPrice": 80,
  "stallsVisited": 3,
  "stallsTotal": 5,
  "lowPrice": 9,
  "highPrice": 11,
  "bowlGrams": 400,
  "bowlPrice": 80,
  "lastYearPrice": 8,
  "townHallQuote": "we have received no written complaints",
  "commentOnePrice": 80
};
  const w_answer = await (async () => {
const slots = w_slots;
const words = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"];
const sample = words[slots.stallsTotal] ?? String(slots.stallsTotal);
const bodyClause = "Body: a sample of " + sample + " stalls, one day; " + slots.lowPrice + "–" + slots.highPrice + " a kilo for field fruit; one " + slots.bowlGrams + " g tasting bowl at " + slots.bowlPrice + " a kilo.";
const headlineClause = "The headline generalises.";
const fieldIsUniform = slots.lowPrice === slots.highPrice;
const firstCommentFollows = fieldIsUniform && slots.commentOnePrice === slots.lowPrice;
const secondCommentFollows = /price/.test(slots.townHallQuote);
const reasons = [];
if (!firstCommentFollows) { reasons.push("the first treats the headline as the body"); }
if (!secondCommentFollows) { reasons.push("the second confuses “no complaints” with “no prices”"); }
const lead = !firstCommentFollows && !secondCommentFollows ? "Neither comment follows" : firstCommentFollows && secondCommentFollows ? "Both comments follow" : "One comment follows";
const commentsClause = reasons.length === 0 ? lead + "." : lead + ": " + reasons.join("; ") + ".";
return bodyClause + " " + headlineClause + " " + commentsClause;
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "kitchenOf": "Mira",
  "place": "Station Quarter",
  "baker": "Mira",
  "tins": "2",
  "flour": 200,
  "water": 100,
  "yeastStep": 1,
  "yeastMinutes": 10,
  "saltStep": 2,
  "kneadStep": 3,
  "kneadMinutes": 8,
  "riseStep": 4,
  "riseMinutes": 60,
  "riseLowC": 24,
  "riseHighC": 26,
  "proofStep": 5,
  "proofMinutes": 20,
  "bakeStep": 6,
  "bakeMinutes": 18,
  "bakeC": 220,
  "coldBelow": 20,
  "coldRise": 90,
  "roomTemp": 18,
  "observedKnead": 4,
  "observedRise": 30,
  "saltWithYeast": true,
  "halvesEverything": true
};
  const w_answer = await (async () => {
const slots = w_slots;
const effectiveRise = slots.roomTemp < slots.coldBelow ? slots.coldRise : slots.riseMinutes;
const respectClause = "Halved ingredients: " + (slots.halvesEverything ? "yes" : "no") + ".";
const breaches = [];
if (slots.saltWithYeast) { breaches.push("salt in S" + slots.yeastStep); }
if (slots.observedKnead !== slots.kneadMinutes) { breaches.push(slots.observedKnead + "-minute knead"); }
if (slots.observedRise !== effectiveRise) { breaches.push(slots.observedRise + "-minute rise"); }
if (slots.observedRise !== slots.coldRise) { breaches.push("ignoring the " + slots.coldRise + " minutes at " + slots.roomTemp + " °C"); }
const breachesClause = breaches.length === 0 ? "Breaches: none." : "Breaches: " + breaches.join("; ") + ".";
return respectClause + " " + breachesClause;
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "place": "Little River",
  "driver": "Sam",
  "arrival": {
    "hour": 7,
    "minute": "10"
  },
  "standMinutes": 15,
  "window": {
    "from": {
      "hour": 6,
      "minute": "00"
    },
    "until": {
      "hour": 8,
      "minute": "00"
    }
  },
  "parkingPlateCancelled": true,
  "exceptionAmendsParking": false,
  "bicyclesAreGoodsVehicles": false,
  "carIsDelivery": false
};
  const w_answer = await (async () => {
const slots = w_slots;
const toMinutes = (hour, minute) => hour * 60 + minute;
const label = (hour, minute) => (minute === "00" ? String(Number(hour)) : Number(hour) + ":" + minute);
const from = toMinutes(slots.window.from.hour, slots.window.from.minute);
const until = toMinutes(slots.window.until.hour, slots.window.until.minute);
const arrival = toMinutes(slots.arrival.hour, slots.arrival.minute);
const windowLabel = label(slots.window.from.hour, slots.window.from.minute) + "–" + label(slots.window.until.hour, slots.window.until.minute);
const parkingBanned = slots.parkingPlateCancelled && !slots.exceptionAmendsParking;
const vanClause = "The van may move in the " + windowLabel + " window but may not stand (cancelled P).";
const carClause = "The car is not a lorry, but it " + (parkingBanned ? "may not park" : "may park") + ".";
const bicycleClause = "The bicycle " + (slots.bicyclesAreGoodsVehicles ? "may not pass" : "may pass") + "; the register is silent on P for bicycles — do not fill the silence.";
return vanClause + " " + carClause + " " + bicycleClause;
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "owner": "Cara",
  "asker": "Drew",
  "runner": "Elena",
  "askTime": "18:01",
  "runnerTime": "18:04",
  "passesAt": "18:20",
  "loaves": "two",
  "ownerReplyTime": "18:06",
  "ownerWithdrew": true,
  "milkRuleTime": "18:07",
  "milkRunner": "Elena",
  "milkLimit": 8,
  "reportTime": "18:25",
  "reportRunner": "Elena",
  "shopFloor": 8,
  "tookOnlyLoaves": true,
  "stopTime": "18:26",
  "stopSaysBuy": false,
  "sentTime": "18:25",
  "walkMinutes": 8,
  "unreadTime": "18:26"
};
  const w_answer = await (async () => {
const slots = w_slots;
const holder = slots.ownerWithdrew ? slots.runner : slots.owner;
const holderClause = holder + " stays on bread.";
const conditionMet = slots.shopFloor < slots.milkLimit;
const boughtMilk = !slots.tookOnlyLoaves;
const milkClause = conditionMet
  ? "Milk: the condition is true, so " + (boughtMilk ? "it was correctly bought" : "it should have been bought") + "."
  : "Milk: the condition is false, so " + (boughtMilk ? "buying it broke the rule" : "correctly not bought") + ".";
const order = slots.stopSaysBuy ? "buy" : "don’t buy";
const respected = boughtMilk === slots.stopSaysBuy;
const stopClause = slots.unreadTime + " was unread and, in any case, said “" + order + "” — " + (respected ? "already respected" : "still open") + ".";
return holderClause + " " + milkClause + " " + stopClause;
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "place": "Little River",
  "family": {
    "name": "Hugo",
    "children": 2,
    "from": "8:00",
    "until": "16:00"
  },
  "rows": [
    {
      "from": "8:00",
      "until": "13:00",
      "one": 400,
      "two": 700,
      "threePlus": 900
    },
    {
      "from": "8:00",
      "until": "16:00",
      "one": 620,
      "two": 1050,
      "threePlus": 1350
    }
  ],
  "lunchPerChild": 180,
  "discount": {
    "amount": 50,
    "place": "Little River"
  },
  "columnsReplaceBaseFee": true
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const row = slots.rows.find((candidate) => candidate.from === slots.family.from && candidate.until === slots.family.until);
const base = slots.family.children === 1 ? row.one : (slots.family.children === 2 ? row.two : row.threePlus);
const discount = slots.discount.place === slots.place ? slots.discount.amount : 0;
const total = base + slots.family.children * slots.lunchPerChild - discount;
probe(total > base, "adding lunch must raise the fee above the hours fee");
return base + " + " + slots.family.children + "×" + slots.lunchPerChild + " − " + discount + " = " + total + ".";
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "place": "Station Quarter",
  "proposer": "Mira",
  "objector": "Ned",
  "conditionalVoter": "Olga",
  "priceCeiling": 800,
  "theirsSpeaker": "Mira",
  "voteRecorded": true,
  "quotesOnlyNoted": true,
  "deferralRecorded": true,
  "ruleAttached": true
};
  const w_answer = await (async () => {
const slots = w_slots;
const voted = "Today " + slots.proposer + "’s proposal (the painting) was voted.";
const deferred = "“This” (" + slots.conditionalVoter + "’s conditional proposal) is deferred.";
const referent = "“He” = " + slots.conditionalVoter + ".";
const quotes = "The three quotes are “noted”, not explicitly voted.";
return voted + " " + deferred + " " + referent + " " + quotes;
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "place": "Little River",
  "fromPrice": 199,
  "stock": 12,
  "plusPrice": 279,
  "discountPercent": 15,
  "deliveryUnder": 20,
  "deliveryThreshold": 300,
  "deliveryFrom": 0,
  "discountStacks": false,
  "coverModel": "Plus",
  "buyer": {
    "name": "Sam",
    "units": "one",
    "day": "Saturday",
    "expectedPrice": 199,
    "expectedDiscount": 15
  }
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const price = slots.plusPrice;
const delivery = price < slots.deliveryThreshold ? slots.deliveryUnder : slots.deliveryFrom;
probe(delivery === slots.deliveryUnder || delivery === slots.deliveryFrom, "the delivery fee must be one of the two printed fees");
const total = price + delivery;
probe(total >= price && total > 0, "the owed sum must cover the model price");
return slots.coverModel + ", " + price + " + delivery " + delivery + " = " + total + ". No " + slots.discountPercent + "%.";
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "place": "Station Quarter",
  "winThreshold": 12,
  "correctBridge": 3,
  "incompleteBridge": 0,
  "forbiddenTalk": 2,
  "extraPieceEndsTurn": true,
  "player": {
    "name": "Cara",
    "start": 10,
    "claimed": 13
  }
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const score = slots.player.start + slots.incompleteBridge - slots.forbiddenTalk;
probe(score < slots.winThreshold, "the earned score must stay under the winning total");
return "Incomplete bridge = " + slots.incompleteBridge + ". Forbidden talk = −" + slots.forbiddenTalk + ". Left with " + score + ". Continuing after the extra piece is forbidden anyway. " + score + " < " + slots.winThreshold + ".";
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "place": "Maple Ward",
  "prices": {
    "roll": 4,
    "sandwich": 8,
    "water": 3
  },
  "cardFloor": 20,
  "noChangeRule": true,
  "buyer": {
    "name": "Ann",
    "rolls": 2,
    "sandwiches": 1,
    "waters": 3,
    "tendered": 50
  },
  "sellerHasChange": true
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const cost = slots.buyer.rolls * slots.prices.roll + slots.buyer.sandwiches * slots.prices.sandwich + slots.buyer.waters * slots.prices.water;
const change = slots.buyer.tendered - cost;
probe(change > 0, "the seller must be able to give change");
probe(cost > slots.prices.water, "the full order must cost more than a single water");
const card = "One water at " + slots.prices.water + " < " + slots.cardFloor + " → card refused.";
return "Cost " + cost + ", change " + change + ". " + card;
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "shop": "Wells Village",
  "customer": "Farid",
  "originalCents": 20000,
  "firstPercent": 10,
  "secondPercent": 5,
  "tillLoyalty": true
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const format = (cents) => Math.trunc(cents / 100) + "." + String(cents % 100).padStart(2, "0");
const reducedCents = Math.round((slots.originalCents * (100 - slots.firstPercent)) / 100);
const paidCents = Math.round((reducedCents * (100 - slots.secondPercent)) / 100);
const wrongCents = Math.round((slots.originalCents * (100 - slots.firstPercent - slots.secondPercent)) / 100);
probe(paidCents < slots.originalCents, "the two-stage discount must lower the ticket");
probe(paidCents > wrongCents, "adding the percents to the original price undercharges, so the wrong method must come out lower");
return format(paidCents) + ". Wrong method " + format(wrongCents) + ", difference " + format(paidCents - wrongCents) + ".";
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "ward": "Maple Ward",
  "borrower": "Kara",
  "capitalCents": 200000,
  "months": 3,
  "ratePercent": 6,
  "latePercent": 1,
  "onTime": true
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const format = (cents) => Math.trunc(cents / 100) + "." + String(cents % 100).padStart(2, "0");
const interestCents = Math.round((slots.capitalCents * Math.round(slots.ratePercent * 100) * slots.months) / 120000);
const termCents = slots.capitalCents + interestCents;
const lateCents = Math.round((slots.capitalCents * Math.round(slots.latePercent * 100)) / 10000);
probe(interestCents > 0, "the simple interest must be positive for a positive rate and term");
probe(termCents === slots.capitalCents + interestCents, "the sum at term must add the interest to the capital");
probe(lateCents === Math.round((slots.capitalCents * slots.latePercent) / 100), "one late month must charge the late percent of the capital alone");
return "Interest " + format(interestCents) + ". At term " + format(termCents) + ". One late month: +" + format(lateCents) + " (" + slots.latePercent + "% of capital, not of the total).";
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "village": "Wells Village",
  "painter": "Piotr",
  "wallWidthCm": 120,
  "wallHeightMeters": 2.5,
  "tinLitres": 2.5,
  "stockedLitres": 2.5,
  "coverageSquareMeters": 12,
  "coats": 1,
  "primed": true
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const format = (hundredths) => Math.trunc(hundredths / 100) + "." + String(hundredths % 100).padStart(2, "0");
const heightCentimetres = Math.round(slots.wallHeightMeters * 100);
const areaHundredths = Math.round((slots.wallWidthCm * heightCentimetres) / 100);
const coverageHundredths = Math.round(slots.coverageSquareMeters * 100) * slots.coats;
probe(Number.isInteger(areaHundredths) && areaHundredths > 0, "the primed wall must have a positive area in whole hundredths of a square metre");
probe(slots.wallWidthCm * heightCentimetres === areaHundredths * 100, "the area must be the wall area in square centimetres divided by ten thousand");
const enough = areaHundredths <= coverageHundredths;
return slots.wallWidthCm + " cm = " + format(slots.wallWidthCm) + " m. Area " + format(areaHundredths) + " m\u00b2. " + (enough ? "Enough" : "Not enough") + " (threshold " + slots.coverageSquareMeters + " m\u00b2).";
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "ward": "Maple Ward",
  "writer": "Ann",
  "litres": [
    4,
    9,
    12
  ],
  "arithmeticMean": true,
  "ratioRule": true
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const format = (hundredths) => Math.trunc(hundredths / 100) + "." + String(hundredths % 100).padStart(2, "0");
const total = slots.litres[0] + slots.litres[1] + slots.litres[2];
const meanHundredths = Math.round((total * 100) / 3);
const smallest = Math.min(slots.litres[0], slots.litres[1], slots.litres[2]);
const largest = Math.max(slots.litres[0], slots.litres[1], slots.litres[2]);
probe(smallest < meanHundredths / 100 && meanHundredths / 100 < largest, "the mean of three numbers must lie between the smallest and the largest");
return "Mean " + format(meanHundredths) + " l. Ratio " + smallest + ":" + largest + ".";
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "saver": "Farid",
  "village": "Wells Village",
  "incomeCents": 300000,
  "fixedCents": 210000,
  "coatCents": 70000,
  "fundPercent": 10,
  "fundFirst": true,
  "noDoubleCount": true
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const format = (cents) => cents % 100 === 0 ? String(cents / 100) : Math.trunc(cents / 100) + "." + String(cents % 100).padStart(2, "0");
const fundCents = Math.round((slots.incomeCents * Math.round(slots.fundPercent * 100)) / 10000);
const remainderCents = slots.incomeCents - fundCents - slots.fixedCents;
probe(fundCents > 0, "the fund must take something from a positive income");
probe(remainderCents >= 0, "the fund and the fixed lines must not exceed the net income");
probe(fundCents + slots.fixedCents + remainderCents === slots.incomeCents, "the fund, the fixed lines, and the remainder must add back to the income");
const fits = remainderCents >= slots.coatCents;
return "Fund " + format(fundCents) + ". Remainder " + format(remainderCents) + ". " + (fits ? "The coat fits." : "The coat does not fit.");
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "place": "Maple Ward",
  "sellerPrice": 120,
  "commissionPercent": 5,
  "deliveryFee": 18,
  "pickupFee": 0,
  "buyer": "Kara"
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const commissionCents = slots.sellerPrice * slots.commissionPercent;
const baseCents = slots.sellerPrice * 100;
const homeCents = baseCents + commissionCents + slots.deliveryFee * 100;
const pickupCents = baseCents + commissionCents + slots.pickupFee * 100;
probe(homeCents > pickupCents, "home delivery must cost more than the pick-up point");
const money = (cents) => (cents / 100).toFixed(2);
return "Commission " + money(commissionCents) + ". Home " + money(homeCents) + ". Pick-up " + money(pickupCents) + ".";
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "shopper": "Piotr",
  "threshold": 5,
  "a": {
    "price": 45,
    "washes": 10,
    "delivery": 0,
    "weight": 4
  },
  "b": {
    "price": 40,
    "washes": 8,
    "delivery": 10,
    "weight": 3
  }
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const perHundredCents = (box) => ((box.price + box.delivery) * 10000) / box.washes;
const aCents = perHundredCents(slots.a);
const bCents = perHundredCents(slots.b);
probe(Number.isInteger(aCents) && Number.isInteger(bCents), "both costs per 100 washes must be whole cents");
const differenceCents = Math.abs(aCents - bCents);
const useWeight = differenceCents < slots.threshold * 100;
const choice = useWeight ? (slots.a.weight <= slots.b.weight ? "A" : "B") : (aCents <= bCents ? "A" : "B");
const money = (cents) => (cents / 100).toFixed(2);
return "A " + money(aCents) + ", B " + money(bCents) + ", difference " + money(differenceCents) + ". Chooses " + choice + ".";
  })();
  console.log(String(w_answer));
})();

(async () => {
  const w_slots = {
  "place": "Maple Ward",
  "people": 40,
  "uncertain": 0,
  "loafRate": 3,
  "saladPerPerson": 200,
  "bottleRate": 4,
  "organiser": "Ann",
  "extraLoaves": 10
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const loaves = Math.ceil(slots.people / slots.loafRate);
const salad = slots.people * slots.saladPerPerson;
