Grid: important+urgent = today; important not urgent = scheduled; urgent not important = delegated/short; neither = dropped.
(1) bill due tomorrow, power will be cut — i+u;
(2) a series — neither;
(3) a “reply now” message about a rumour — u, not i, says the notebook;
(4) a medical check that can be booked this month — i, not u.

Question. The grid’s order?

(async () => {
  const w_slots = {
  "grid": {
    "both": "today",
    "important": "scheduled",
    "urgent": "delegated/short",
    "neither": "dropped"
  },
  "items": [
    {
      "n": 1,
      "tag": "i+u"
    },
    {
      "n": 2,
      "tag": "neither"
    },
    {
      "n": 3,
      "tag": "u, not i, says the notebook"
    },
    {
      "n": 4,
      "tag": "i, not u"
    }
  ]
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const classify = (tag) => {
  if (/i\+u/.test(tag)) return "both";
  if (/neither/.test(tag)) return "neither";
  if (/u, not i/.test(tag)) return "urgent";
  if (/i, not u/.test(tag)) return "important";
  throw new Error("the item tag " + tag + " does not name a cell of the grid");
};
const rank = { both: 0, important: 1, urgent: 2, neither: 3 };
const ordered = slots.items.map((item) => {
  const cls = classify(item.tag);
  return { n: item.n, rank: rank[cls], label: cls === "urgent" ? "short/delegated" : slots.grid[cls] };
}).sort((left, right) => left.rank - right.rank);
probe(ordered[0].label === slots.grid.both, "the first chore must sit in the both-cells of the grid");
probe(ordered[3].label === slots.grid.neither, "the last chore must sit in the neither cell of the grid");
return ordered.map((item) => "(" + item.n + ") " + item.label).join("; ") + ".";
  })();
  console.log(String(w_answer));
})();

