  "depot": "hill depot",
  "unit": "crates",
  "values": [
    35,
    25,
    40,
    34,
    16,
    22,
    36
  ],
  "threshold": 21,
  "pct": 50
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const values = slots.values;
let current = values;
// stage 1: keepAbove
const kept0 = current.filter((value) => value > slots.threshold);
current = kept0;
// stage 2: total
const total1 = current.reduce((sum, value) => sum + value, 0);
current = total1;
// stage 3: percentOf
const adjusted2 = (current * slots.pct) / 100;
current = adjusted2;
probe(Number.isInteger(current) && current >= 0, "the answer must be a whole number that is not negative");
return current + " units.";
  })();
  console.log(String(w_answer));
})();

