(async () => {
  const w_slots = {
  "depot": "hill depot",
  "unit": "days",
  "values": [
    14,
    19,
    12,
    41,
    29,
    27
  ],
  "threshold": 20,
  "rate": 3,
  "per": 24,
  "label": "hours"
};
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
const values = slots.values;
let current = values;
// stage 1: keepBelow
const kept0 = current.filter((value) => value < slots.threshold);
current = kept0;
// stage 2: count
const count1 = current.length;
current = count1;
// stage 3: elapsed
const adjusted2 = current * slots.per;
current = adjusted2;
// stage 4: addRate
const adjusted3 = current + slots.rate;
current = adjusted3;
probe(Number.isInteger(current) && current >= 0, "the answer must be a whole number that is not negative");
return current + " units.";
  })();
  console.log(String(w_answer));
})();

