    },
    {
      "id": "H2",
      "claim": "the batches steps ran in the wrong order",
      "kind": "ordering"
    },
    {
      "id": "H3",
      "claim": "the batches handling had insufficient capacity",
      "kind": "capacity"
    }
  ],
  "observations": [
    {
      "kind": "capacity-availability",
      "availableUnits": 27
    },
    {
      "kind": "ordering-violation"
    },
    {
