probe(keptTop.every((value, index) => value === ranked[index]), "the kept values must be the leading part of the ranking");
return keptTop;
  })();
  const w_answer = await (async () => {
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
const slots = w_slots;
